if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
  S.o1 = fr(1)*30; S.o2 = fr(2)*30; S.hoff = fr(5); S.tw = fr(6)*TAU;
}
const sd = P.seed | 0;
function hsh(ix,iy){ let h=(ix*374761393 + iy*668265263 + sd*2147483647)|0; h=(h^(h>>13))*1274126177|0; return ((h^(h>>16))>>>0)/4294967295; }
function vn(x,y){ const ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy,u=fx*fx*(3-2*fx),v=fy*fy*(3-2*fy); const a=hsh(ix,iy),b=hsh(ix+1,iy),c=hsh(ix,iy+1),d=hsh(ix+1,iy+1); return a+(b-a)*u+(c-a)*v+(a-b-c+d)*u*v; }
function fbm(x,y){ return 0.58*vn(x,y) + 0.28*vn(x*2.02+5.1, y*2.02-3.2) + 0.14*vn(x*4.05-2.3, y*4.05+7.7); }

const spd = cl(P.speed,0.1,3);
const en = cl(P.energy,0,1);
const sc = cl(P.scale,0.4,2.4);
const dens = cl(P.density,0,1);
const W = 0.3 + cl(P.warp,0,1)*3.2;                                      // domain-warp strength (1st poke)
const ordersN = 1.3 + cl(P.orders,0,1)*4.7 + sc*0.4 + K.intensity*0.7;   // rainbow band count (2nd poke) + arc swell
const zoom = 3.0/(0.4 + sc*1.1);
