const drift = K.t * spd * 0.055 + K.section*0.05;                        // spectral-band crawl (motion floor + arc)
const ex = 0.5 + en*0.72 + K.intensity*0.28 + A.rms*0.5;                 // exposure (audio on top of baseline)
const h0 = ((P.hue/360) + S.hoff*0.5) % 1;
const ox = S.o1 - (P.x-0.5)*1.2, oy = S.o2 - (P.y-0.5)*1.2;
const treb = A.treble, bassW = A.bass*0.05;
const style = P.style;
