for (let j=0;j<BH;j++){
  for (let i=0;i<BW;i++){
    const nx = (i/BW - 0.5)*zoom*(BW/BH) + ox;
    const ny = (j/BH - 0.5)*zoom + oy;
    // domain warp (2 iterations) -> organic flowing slick blobs
    const q1 = fbm(nx + boil*0.5, ny + 1.7);
