      const sheen = edge*0.12*dens;
      r += sheen; gg += sheen; b += sheen;
    } else if (style==='nacre'){
      // mother-of-pearl: pale low-sat cool shimmer over pearly base
      const pr = 0.5+0.5*Math.cos(TAU*(ph + 0.10));
